// What the browser needs to build a track from an image: load it and reduce it to a mask of dark pixels
// (imageMask). The rest (buildTrackFromMask, in track.js) also runs in Node.
import { buildTrackFromMask } from '../sim/track.js';

export function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Could not load ${src}`));
    img.src = src;
  });
}

// elevation (optional): height profile generated by tools/elevation.py
export function buildTrack(img, def, elevation = null) {
  return buildTrackFromMask(imageMask(img, def), def, elevation);
}

// Dark pixels of the reduced image (1 = may be track): the only part that needs the browser
export function imageMask(img, def) {
  const scale = def.scale ?? 3;
  const W = Math.ceil(img.width / scale);
  const H = Math.ceil(img.height / scale);
  const threshold = def.threshold ?? 90;
  // Reduce the image: each resulting pixel is the average of scale×scale pixels
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, W, H);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(img, 0, 0, W, H);
  // hand touch-ups, in image pixels: `paint` draws over in black the track sections the drawing covers
  // (e.g. with the checkered flag): [[x0, y0, x1, y1, width], ...]
  ctx.save();
  ctx.scale(W / img.width, H / img.height);
  ctx.strokeStyle = '#000';
  ctx.lineCap = 'round';
  for (const [x0, y0, x1, y1, width] of def.paint ?? []) {
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x1, y1);
    ctx.stroke();
  }
  ctx.restore();
  const px = ctx.getImageData(0, 0, W, H).data;

  const road = new Uint8Array(W * H);
  for (let i = 0; i < W * H; i++) {
    const lum = 0.299 * px[i * 4] + 0.587 * px[i * 4 + 1] + 0.114 * px[i * 4 + 2];
    road[i] = lum < threshold ? 1 : 0;
  }
  return { W, H, road };
}
